    for (let i: u32 = 0; i < count; i++) if (mapFind(load<u32>(root + 16 + i * 4), key, len, hash)) { pos = i; break; }
    if (pos == count) return root;
    if (count == 2) return load<u32>(root + 16 + (1 - pos) * 4);
    const p = bucket(hash, count - 1);
