    // not depend on hash uniqueness; this rare path can be quadratic in count.
    let added: u32 = 0;
    for (let i: u32 = 0; i < count; i++) { old = insertAt(old, load<u32>(input + i * 4), shift, 0xffffffff, mark); added += insertedCount; }
