  const p = mapFind(root, 0, len, hashAt(0, len));
  if (p) { store<u32>(1024, load<u32>(p + 8)); store<u32>(1028, load<u32>(p + 12)); store<u32>(1032, p + 16); }
  return p;
}

// Dense persistent vector: 32 f64 values per leaf, 32 u32 pointers per branch.
